// Package postgres opens the platform's database (PostgreSQL, --database / ACADEMY_DATABASE_URL; `make db` runs one
// in Docker): created if missing, the embedded goose migrations applied at start. Queries are generated by sqlc
// from queries.sql (*.gen.go), on database/sql over the pgx/v5 driver.
package postgres

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/stdlib" // database/sql driver "pgx"
	"github.com/pressly/goose/v3"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/platform"
	"github.com/IhebBelhadj/opsforge-academy/academy/migrations"
)

// DefaultURL is `make db`'s container: 127.0.0.1 only, its password no secret (a real deployment sets its own URL).
const DefaultURL = "postgres://academy:academy@127.0.0.1:5433/academy?sslmode=disable" //nolint:gosec // see above

// Store is the open database with its generated queries.
type Store struct {
	DB      *sql.DB
	Queries *Queries
	goose   *goose.Provider
}

// Open connects to the database at url (creating it when the server has none by that name), applies pending
// migrations and records the instance.
func Open(ctx context.Context, url string, clock platform.Clock) (*Store, error) {
	if err := ensure(ctx, url); err != nil {
		return nil, fmt.Errorf("database %s: %w", Redact(url), err)
	}
	config, err := pgx.ParseConfig(url)
	if err != nil {
		return nil, fmt.Errorf("database %s: %w", Redact(url), err)
	}
	db := stdlib.OpenDB(*config, stdlib.OptionAfterConnect(utc))
	db.SetMaxOpenConns(10)
	store, err := setup(ctx, db, clock)
	if err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("database %s: %w", Redact(url), err)
	}
	return store, nil
}

// utc makes the connection read timestamps in UTC (as they are written), not in the host's zone.
func utc(_ context.Context, conn *pgx.Conn) error {
	conn.TypeMap().RegisterType(&pgtype.Type{Name: "timestamptz", OID: pgtype.TimestamptzOID,
		Codec: &pgtype.TimestamptzCodec{ScanLocation: time.UTC}})
	return nil
}

// ensure creates the database url names when it does not exist (as the SQLite file was), through the server's
// maintenance database.
func ensure(ctx context.Context, dbURL string) error {
	db, err := sql.Open("pgx", dbURL)
	if err != nil {
		return err
	}
	defer func() { _ = db.Close() }()
	err = db.PingContext(ctx)
	var pe *pgconn.PgError
	if !errors.As(err, &pe) || pe.Code != "3D000" { // invalid_catalog_name: no such database
		return err
	}
	u, err := url.Parse(dbURL)
	if err != nil {
		return err
	}
	name := strings.TrimPrefix(u.Path, "/")
	u.Path = "/postgres"
	admin, err := sql.Open("pgx", u.String())
	if err != nil {
		return err
	}
	defer func() { _ = admin.Close() }()
	_, err = admin.ExecContext(ctx, "CREATE DATABASE "+QuoteIdent(name))
	if errors.As(err, &pe) && pe.Code == "42P04" { // duplicate_database: made meanwhile
		return nil
	}
	return err
}

// QuoteIdent is name as an SQL identifier.
func QuoteIdent(name string) string { return `"` + strings.ReplaceAll(name, `"`, `""`) + `"` }

// Redact is url without its password (for messages).
func Redact(dbURL string) string {
	u, err := url.Parse(dbURL)
	if err != nil {
		return "(invalid url)"
	}
	return u.Redacted()
}

func setup(ctx context.Context, db *sql.DB, clock platform.Clock) (*Store, error) {
	provider, err := goose.NewProvider(goose.DialectPostgres, db, migrations.FS)
	if err != nil {
		return nil, fmt.Errorf("migrations: %w", err)
	}
	if _, err := provider.Up(ctx); err != nil {
		return nil, fmt.Errorf("migrate: %w", err)
	}
	queries := New(db)
	if err := queries.InitInstance(ctx, clock.Now()); err != nil {
		return nil, fmt.Errorf("instance: %w", err)
	}
	return &Store{DB: db, Queries: queries, goose: provider}, nil
}

// Ready reports whether the database answers and has every migration applied (readyz).
func (s *Store) Ready(ctx context.Context) error {
	if err := s.DB.PingContext(ctx); err != nil {
		return err
	}
	pending, err := s.goose.HasPending(ctx)
	if err != nil {
		return err
	}
	if pending {
		return errors.New("migrations pending")
	}
	return nil
}

// Close closes the connections.
func (s *Store) Close() error { return s.DB.Close() }

// IsUniqueViolation reports whether err is a unique constraint failing (a row a unique index refuses).
func IsUniqueViolation(err error) bool {
	var pe *pgconn.PgError
	return errors.As(err, &pe) && pe.Code == "23505"
}

// Time is t as the database keeps it: timestamptz has microseconds, so a time read back equals Time(t).
func Time(t time.Time) time.Time { return t.UTC().Truncate(time.Microsecond) }
